    pts=np.array(sorted(set(map(tuple,cells))))
    n=len(pts)
    if n==1: return {tuple(p)}
    # convex hull via sorted corners (shoelace), monotone chain
    def cross(a,b,c):
        return (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])
    pts=sorted(map(tuple,set(cells)))
