bg=6
def solve(A):
    H,W=A.shape; bg=A.max()# placeholder
    bgs=sorted(set(A.flatten()))
    bg=bgs[0]  # assume smallest value is background
    seen=set(); out=A.copy()
    for r in range(H):
        for c in range(W):
            if A[r][c]!=bg and (r,c) not in seen:
                v=A[r][c]; stack=[(r,c)]; cells=[]
                while stack:
                    y,x=stack.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and A[ny][nx]==v: stack.append((ny,nx))
                moved=True
                for r_,c_ in cells:
                    if c_+1>=W: moved=False;break
                if moved:
                    for r_,c_ in cells: out[r_][c_+1]=v
                for r_,c_ in cells:
                    if out[r_][c_]==v and not moved: pass
                    # vacate: set to bg if not overwritten
                    if out[r_][c_]==v and True: out[r_][c_]=bg
                elif not moved:
                    # stays; but do we also need to clear original? no
                    pass
    return out
