def sim(I):
    I=np.array(I); H,W=I.shape
    cnt=Counter(int(x) for row in I for x in row); bg=cnt.most_common(1)[0][0]
    R=I.copy()
    # each non-bg cell falls: prefer diagonal (down-right), then straight down, then right; stop if blocked
    changed=True
    history=[]
    while changed:
        changed=False
        for r in range(H-1,-1,-1):
            for c in range(W):
                v=R[r,c]
                if v==bg: continue
                res={}
                # diagonal
                ny,nx=r+1,c+1
                d_=(None,None,None)
                if 0<=ny<H and 0<=nx<W and R[ny,nx]==bg: res['diag']=True; d_=(ny,nx,bg)
                elif 0<=ny<H and 0<=nx<W: res['downright']=True; d_=(ny,nx,R[ny,nx])
                else: res['diag']=False; d_=None
                if 'diag' in res and res['diag']:
                    R[r,c]=bg; R[ny,nx]=v; changed=True; break
                ny,nx=d_[0],d_[1]
                if 0<=ny<H and 0<=nx<W and R[ny,nx]==bg:
                    R[r,c]=bg; R[ny,nx]=v; changed=True; break
        # no diag attempt: try straight down
        changed2=False
        for r in range(H-1,-1,-1):
            for c in range(W):
                v=R[r,c]
                if v==bg: continue
                if 0<=r+1<H and R[r+1,c]==bg:
                    R[r,c]=bg; R[r+1,c]=v; changed2=True; break
        if not changed2:
            for r in range(H):
                for c in range(W-1):
                    v=R[r,c]
                    if v!=bg and R[r,c+1]==bg:
                        R[r,c]=bg; R[r,c+1]=v; changed2=True; break
            changed=changed2
    return R.tolist()

